-- Additive operational redesign. Full pre-change rows retained outside Data API.
create schema if not exists sudmar_backup;
revoke all on schema sudmar_backup from public, anon, authenticated;
create table sudmar_backup.operational_20260925 as
select 'tickets'::text entity,to_jsonb(t) data from public.tickets t
union all select 'tasks',to_jsonb(t) from public.tasks t
union all select 'personnel',to_jsonb(t) from public.personnel t
union all select 'clients',to_jsonb(t) from public.clients t
union all select 'equipment',to_jsonb(t) from public.equipment t;
revoke all on sudmar_backup.operational_20260925 from public, anon, authenticated;
alter table sudmar_backup.operational_20260925 enable row level security;

create function public.catalog_key(value text) returns text language sql immutable set search_path='' as $$ select upper(regexp_replace(btrim(value),'\s+',' ','g')) $$;
create table public.service_categories(id uuid primary key default gen_random_uuid(),business_unit text not null check(business_unit in ('SUDMAR','PRETTL')),name text not null check(length(btrim(name)) between 2 and 120), name_key text generated always as (public.catalog_key(name)) stored,unique(business_unit,name_key));
create table public.equipment_models(id uuid primary key default gen_random_uuid(),name text not null check(length(btrim(name)) between 1 and 120),equipment_type text not null check(length(btrim(equipment_type)) between 2 and 120),name_key text generated always as(public.catalog_key(name)) stored unique);
create table public.equipment_serials(id uuid primary key default gen_random_uuid(),model_id uuid not null references public.equipment_models(id),serial_number text not null check(length(btrim(serial_number)) between 1 and 120),serial_key text generated always as(public.catalog_key(serial_number)) stored,source_row integer,unique(model_id,serial_key));
create table public.activity_types(id uuid primary key default gen_random_uuid(),name text not null check(length(btrim(name)) between 2 and 120),name_key text generated always as(public.catalog_key(name)) stored unique);
create table public.activity_statuses(name text primary key,group_code text not null check(group_code in ('POR INICIAR','EN CURSO','DETENIDA','CERRADA')),description text not null, is_cancelled boolean not null default false, check(not is_cancelled or group_code='CERRADA'),check(public.catalog_key(name) not in ('REPROGRAMADA','NO REALIZADA','TÉCNICO NO ACUDIÓ','TECNICO NO ACUDIO','TÉCNICO NO PUDO ACUDIR')),name_key text generated always as(public.catalog_key(name)) stored unique);
insert into public.activity_statuses(name,group_code,description,is_cancelled) values
('POR INICIAR','POR INICIAR','Registrada, aún no comienza.',false),
('EN EJECUCIÓN','EN CURSO','Actualmente se realizan trabajos.',false),
('EN ESPERA','DETENIDA','Depende de cliente, refacción, información, acceso, autorización u otro factor externo.',false),
('BLOQUEADA','DETENIDA','Existe un impedimento que no permite continuar.',false),
('COMPLETADA','CERRADA','Los trabajos definidos fueron terminados.',false),
('CANCELADA','CERRADA','La actividad ya no se ejecutará.',true);

do $$ declare t text; begin
foreach t in array array['service_categories','equipment_models','equipment_serials','activity_types','activity_statuses'] loop
 execute format('alter table public.%I enable row level security',t);
 execute format('grant select,insert on public.%I to anon',t);
 execute format('create policy pilot_catalog_read on public.%I for select to anon using (true)',t);
 execute format('create policy pilot_catalog_insert on public.%I for insert to anon with check (true)',t);
end loop; end $$;
grant insert on public.clients to anon;
create policy platform_insert_clients on public.clients for insert to anon with check (true);
-- Keep existing duplicates and all foreign keys; prevent any new spelling-only duplicates.
create function public.prevent_duplicate_client() returns trigger language plpgsql set search_path='' as $$
begin
 perform pg_advisory_xact_lock(hashtextextended(public.catalog_key(new.name),0));
 if exists(select 1 from public.clients c where public.catalog_key(c.name)=public.catalog_key(new.name) and c.id<>new.id) then raise exception 'El cliente ya existe en el catálogo.' using errcode='23505'; end if;
 new.name:=regexp_replace(btrim(new.name),'\s+',' ','g'); return new;
end $$;
create trigger prevent_duplicate_client before insert or update of name on public.clients for each row execute function public.prevent_duplicate_client();
create index clients_name_key_idx on public.clients(public.catalog_key(name));
insert into public.clients(name) select 'ENERGÍA ADAPTABLE' where not exists(select 1 from public.clients where public.catalog_key(name) in ('ENERGÍA ADAPTABLE','ENERGIA ADAPTABLE'));

alter table public.personnel add column operational_areas text[],add column legacy_role text,add column legacy_area text;
update public.personnel set legacy_role=role,legacy_area=area,operational_areas=array[area];
update public.personnel set role='Gerencia de Ventas',area='Ventas',operational_areas=array['Ventas'] where name in ('Saul Gonzalez','Saúl González');
update public.personnel set role=role||' / Ventas',operational_areas=array[area,'Ventas'] where name='Manuel Cervantes';

alter table public.tickets add column operational_status text check(operational_status in ('REGISTRADO','PROGRAMADO','EN EJECUCIÓN','EN ESPERA','BLOQUEADO','PENDIENTE DE VALIDACIÓN','CONCLUIDO','CANCELADO')),
add column legacy_status text,add column legacy_stage text,add column legacy_diagnosis text,
add column service_category_id uuid references public.service_categories(id),
add column catalog_model_id uuid references public.equipment_models(id),
add column catalog_serial_id uuid references public.equipment_serials(id),
add column request_context jsonb,add column technical_findings text,add column work_performed text,add column final_condition text;
update public.tickets set legacy_status=status,legacy_stage=stage,legacy_diagnosis=diagnosis,
 operational_status=case
 when upper(stage)='CONCLUIDO' and upper(status) in ('CERRADO','ABIERTO') then 'CONCLUIDO'
 when upper(status) in ('CONCLUIDO','CONCLUIDA') then 'CONCLUIDO'
 when upper(status) in ('CANCELADO','CANCELADA') then 'CANCELADO'
 when upper(status)='NUEVA' then 'REGISTRADO'
 when upper(status)='EN PROCESO' or upper(stage)='EN PROCESO' then 'EN EJECUCIÓN'
 when upper(status)='EN ESPERA' then 'EN ESPERA'
 else null end;
-- Unknown historical operational states deliberately remain NULL pending human classification.
create index tickets_operational_status_idx on public.tickets(operational_status);
create index tickets_catalog_model_idx on public.tickets(catalog_model_id);
create index tickets_category_idx on public.tickets(service_category_id);
create index tickets_catalog_serial_idx on public.tickets(catalog_serial_id);

