update public.tickets t set catalog_model_id=m.id from public.equipment_models m where public.catalog_key(t.source_model)=m.name_key;
update public.tickets t set catalog_serial_id=s.id from public.equipment_serials s where t.catalog_model_id=s.model_id and public.catalog_key(t.source_serial)=s.serial_key;

create or replace function public.sync_ticket_operational_dates() returns trigger language plpgsql set search_path='' as $$
declare terminal boolean; old_terminal boolean; model uuid;
begin
 new.opened_at:=coalesce(new.opened_at,now());
 if (tg_op='INSERT' or new.business_unit is distinct from old.business_unit) and coalesce(new.business_unit,'') not in ('SUDMAR','PRETTL') then raise exception 'Selecciona SUDMAR o PRETTL.'; end if;
 if tg_op='INSERT' then new.operational_status:=coalesce(new.operational_status,'REGISTRADO'); end if;
 if new.operational_status is not null then
   terminal:=new.operational_status in ('CONCLUIDO','CANCELADO');
   old_terminal:=case when tg_op='UPDATE' then coalesce(old.operational_status in ('CONCLUIDO','CANCELADO'),false) else false end;
   if terminal then new.closed_at:=coalesce(new.closed_at,now());
   elsif tg_op='INSERT' or old_terminal or (tg_op='UPDATE' and new.operational_status is distinct from old.operational_status) then new.closed_at:=null; end if;
   new.status:=new.operational_status;
 end if;
 if new.service_category_id is not null and not exists(select 1 from public.service_categories c where c.id=new.service_category_id and c.business_unit=new.business_unit) then raise exception 'La categoría no corresponde a la unidad.'; end if;
 if new.catalog_serial_id is not null then
   select model_id into model from public.equipment_serials where id=new.catalog_serial_id;
   if model is distinct from new.catalog_model_id then raise exception 'La serie no corresponde al modelo.'; end if;
 end if;
 if new.due_at < new.opened_at then raise exception 'La meta no puede ser anterior al inicio.'; end if;
 if new.request_context is not null then
   if exists(select 1 from unnest(array['what','where','condition','required']) k where length(btrim(coalesce(new.request_context->>k,'')))<4) then raise exception 'Completa los cuatro campos de la solicitud.'; end if;
   new.description:=concat(new.request_context->>'what',' · ',new.request_context->>'where',' · ',new.request_context->>'condition','. Se requiere: ',new.request_context->>'required');
   new.title:=left(new.description,180);
 end if;
 return new;
end $$;

alter table public.tasks add column antecedent_ticket_id uuid references public.tickets(id),add column activity_status text references public.activity_statuses(name),add column legacy_status text;
create index tasks_antecedent_idx on public.tasks(antecedent_ticket_id);
create index tasks_activity_status_idx on public.tasks(activity_status);
update public.tasks set legacy_status=status,activity_status=case upper(status) when 'SIN INICIAR' then 'POR INICIAR' when 'EN PROCESO' then 'EN EJECUCIÓN' when 'EN ESPERA' then 'EN ESPERA' when 'BLOQUEADA' then 'BLOQUEADA' when 'COMPLETADA' then 'COMPLETADA' when 'CANCELADA' then 'CANCELADA' else null end;
create function public.sync_activity_operational_state() returns trigger language plpgsql set search_path='' as $$
declare group_name text;
begin
 if tg_op='INSERT' then new.activity_status:=coalesce(new.activity_status,'POR INICIAR'); end if;
 if new.activity_status is not null then
  select group_code into group_name from public.activity_statuses where name=new.activity_status;
  new.status:=new.activity_status;
  if group_name='CERRADA' then
   if length(btrim(coalesce(new.resolution,'')))=0 or length(btrim(coalesce(new.outcome,'')))=0 then raise exception 'Registra resultado y resolución para cerrar.'; end if;
   new.completed_at:=coalesce(new.completed_at,now());
  else new.completed_at:=null; end if;
 end if;
 if new.antecedent_ticket_id=new.ticket_id then raise exception 'El antecedente debe ser otra atención.'; end if;
 return new;
end $$;
create trigger sync_activity_operational_state before insert or update on public.tasks for each row execute function public.sync_activity_operational_state();
